package com.pulsefit.subscription;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="subscriptions") public class Subscription { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; Long memberId; Long planId; LocalDate startDate; LocalDate endDate; String status="ACTIVE"; public Subscription(){} public Long getId(){return id;} public Long getMemberId(){return memberId;} public void setMemberId(Long v){memberId=v;} public Long getPlanId(){return planId;} public void setPlanId(Long v){planId=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
